{
  "type": "h2",
  "text": "Commercial charter regimes, by jurisdiction"
},
{
  "type": "kv",
  "caption": "Commercial registration is decided jurisdiction by jurisdiction; there is no single global licence. The VAT regimes that interact with charter are in chapter 4.",
  "rows": [
    {
      "label": "France",
      "value": "French Commercial Exemption (FCE): commercial registration, full-time crew, length above 15 m.",
      "note": "Its VAT conditions, including the share of voyages leaving French waters and the limit on static charter use, are set out in chapter 4."
    },
    {
      "label": "Italy",
      "value": "Italian flag with commercial registration, or a non-Italian flag meeting Codice della Nautica conditions. VAT on charter fees is 22 percent on the portions in Italian waters.",
      "note": "Italian leasing and its effective-use test: chapter 4."
    },
    {
      "label": "Spain",
      "value": "Royal Decrees 186/2023 and 587/2024 replace the charter licence with an Affidavit of Responsibility filed with the Harbour Master, for EU and non-EU flags alike; 2026 is the transition year.",
      "note": "Spanish residents and entities established in Spain register yachts locally and pay the special tax on certain means of transport at 12 percent of value (11 percent in the Canary Islands); yachts used exclusively for charter can be exempt, subject to conditions on use by owners and their families."
    },
    {
      "label": "Greece",
      "value": "Historically the most restrictive in the Mediterranean. Greek-flagged and EU-flagged yachts above 35 m can charter under the standard regime. Since February 2024 the e-Charter Permission also lets non-EU-flagged commercial yachts over 35 m with non-wooden hulls charter in Greek waters for up to 28 days a year, subject to a special fee and VAT registration.",
      "note": "NEPA is the long-form route."
    },
    {
      "label": "Croatia",
      "value": "Croatian flag or a local charter-agency arrangement under the Croatian Maritime Code. Annual permit.",
      "note": "13 percent VAT on charter fees."
    },
    {
      "label": "Turkey",
      "value": "“Blue Cruise” charter requires Turkish-flag operation or a Turkish charter agreement with a licensed local operator.",
      "note": "Foreign-flagged yachts can cruise privately; commercial charter requires the local licence."
    },
    {
      "label": "Monaco",
      "value": "The Monégasque flag permits up to 90 days of commercial charter a year without personal tax levies on the owner; under several neighbouring EU flags the same vessel would face VAT on private owner use.",
      "note": "Visible reflagging at brokerage during 2026 on yachts of 30 to 50 m with light charter intent (Capt. Ukic of M/Y Ellen, MYBA Charter Show 2026, in The Superyacht Report)."
    },
    {
      "label": "Cayman Islands and Marshall Islands",
      "value": "Both issue commercial certificates covering global charter activity. Cayman applies the Red Ensign Group Yacht Code (July 2024 edition), the Marshall Islands its own Yacht Code (2026 edition).",
      "note": "The dominant choices for over-30 m commercial programmes."
    },
    {
      "label": "Malta",
      "value": "An EU charter route widely used for long Mediterranean seasons.",
      "note": "VAT on a lease under the Maltese leasing guidelines (in force since March 2020) follows documented use: chapter 4."
    },
    {
      "label": "United States",
      "value": "Regulated under federal law (Coast Guard and the Jones Act). Foreign-flagged yachts cannot embark and disembark passengers between US ports under standard charter, which severely restricts non-US-flagged commercial operation in US waters.",
      "note": "The US tax treatment of a charter business is in the chapter essay."
    }
  ],
  "sourceLine": "Royal Decrees 186/2023 and 587/2024 (Spain); Greek e-Charter Permission (February 2024); Red Ensign Group Yacht Code (July 2024); Marshall Islands Yacht Code (2026); The Superyacht Report (Monaco)."
}

